// Ping's spoken lines. One shared <audio> element, so two clips can never play at once.
// Files: public/voice/<voiceKey(text)>.mp3, durations in public/voice/index.json
// (generated by tools/narration – lines without a recording simply stay silent).
import { voiceKey } from './voiceKey';
import { duckMusic, getCtx } from './audio';
import { useSettings } from '../game/settings';
import { useGame } from '../game/store';
import { logWarn } from '../game/log';

const BASE = `${import.meta.env.BASE_URL}voice/`;
let manifest = {};
fetch(`${BASE}index.json`)
  .then((r) => (r.ok ? r.json() : {}))
  .then((m) => { manifest = m || {}; })
  .catch(() => logWarn('narration', 'voice/index.json missing – narration off'));

const player = typeof Audio !== 'undefined' ? new Audio() : null;
if (player) {
  player.preload = 'auto';
  player.addEventListener('ended', () => duckMusic(false));
  player.addEventListener('pause', () => duckMusic(false));
}

export const narrationOn = () => useSettings.getState().narration !== false && !useGame.getState().muted;

/** Seconds the recording of this text lasts (0 if there is none or narration is off). */
export function voiceDuration(text) {
  if (!narrationOn()) return 0;
  return manifest[voiceKey(text)] || 0;
}

/* Ping's mouth follows the loudness of her voice: the clip is routed through an analyser. */
let analyser = null, levels = null, routed = false;
function routeThroughAnalyser() {
  if (routed || !player) return;
  try {
    const ctx = getCtx();
    if (!ctx || ctx.state !== 'running') return; // before the first click: keep the plain <audio> path
    const src = ctx.createMediaElementSource(player);
    analyser = ctx.createAnalyser();
    analyser.fftSize = 512;
    analyser.smoothingTimeConstant = 0.35;
    levels = new Float32Array(analyser.fftSize);
    src.connect(analyser);
    analyser.connect(ctx.destination);
    routed = true;
  } catch (e) {
    routed = true; // never try twice
    logWarn('narration', `no level meter for the mouth: ${e.message}`);
  }
}
/** 0..1 loudness of Ping's voice right now; -1 when it can't be measured (then the mouth uses a rhythm). */
export function voiceLevel() {
  if (!player || player.paused) return 0;
  if (!analyser) return -1;
  analyser.getFloatTimeDomainData(levels);
  let sum = 0;
  for (let i = 0; i < levels.length; i++) sum += levels[i] * levels[i];
  return Math.min(1, Math.sqrt(sum / levels.length) * 5.5);
}
/** True while a recorded line is playing. */
export const voicePlaying = () => Boolean(player && !player.paused && !player.ended);

export function playVoice(text) {
  if (!player) return;
  stopVoice();
  if (!narrationOn()) return;
  const key = voiceKey(text);
  if (!manifest[key]) return;
  routeThroughAnalyser();
  player.src = `${BASE}${key}.mp3`;
  player.volume = 0.95;
  duckMusic(true);
  player.play().catch(() => duckMusic(false)); // blocked before the first click – the bubble text is still there
}

export function stopVoice() {
  if (player && !player.paused) player.pause();
  duckMusic(false);
}
